"""Safety Alert API client for Home Assistant integration.""" from __future__ import annotations
import aiohttp from datetime import datetime, timedelta from typing import Dict, Any, List, Optional
from .exceptions import SafetyAlertConnectionError, SafetyAlertDataError from ..const import LOGGER
class SafetyAlertApiClient: """API client for Safety Alert integration."""
def __init__(self, session: aiohttp.ClientSession) -> None: """Initialize the Safety Alert API client.""" self._session: aiohttp.ClientSession = session self._base_url: str = "https://www.safekorea.go.kr/idsiSFK/sfk/cs/sua/web/DisasterSmsList.do"
async def async_get_safety_alerts( self, area_code: str = "1156000000", area_code2: Optional[str] = None, area_code3: Optional[str] = None ) -> List[Dict[str, Any]]: """Get safety alerts for the specified areas.""" # Calculate date range (last 7 days) end_date = datetime.now() start_date = end_date - timedelta(days=7)
# Prepare request payload with all area codes payload = { "searchInfo": { "firstIndex": "1", "rcv_Area_Id": "", "pageIndex": "1", "sbLawArea1": area_code, # 첫 번째 지역 코드 "dstr_se_Id": "", "lastIndex": "1", "searchBgnDe": start_date.strftime("%Y-%m-%d"), "searchEndDe": end_date.strftime("%Y-%m-%d"), "sbLawArea3": area_code3 if area_code3 else "", # 세 번째 지역 코드 "recordCountPerPage": "50", "searchWrd": "", "searchGb": "1", "c_ocrc_type": "", "sbLawArea2": area_code2 if area_code2 else "", # 두 번째 지역 코드 "pageUnit": "50", "pageSize": 50 } }
headers = { "Content-Type": "application/json", "Accept": "application/json", "User-Agent": "HomeAssistant-Korea-Components/1.0" }
try: async with self._session.post( self._base_url, json=payload, headers=headers ) as response: LOGGER.debug(f"Safety Alert API response status: {response.status}")
if response.status != 200: LOGGER.warning(f"Failed to get alerts: HTTP {response.status}") raise SafetyAlertConnectionError(f"HTTP {response.status}")
data = await response.json() LOGGER.debug(f"Safety Alert API response: {data}")
alerts = data.get("disasterSmsList", [])
# 생성일시 기준으로 정렬 (최신순) alerts.sort(key=lambda x: x.get("CREAT_DT", ""), reverse=True)
return alerts
except aiohttp.ClientError as e: LOGGER.error(f"Safety Alert API request failed: {e}") raise SafetyAlertConnectionError(f"Connection failed: {e}") except Exception as e: LOGGER.error(f"Unexpected error in Safety Alert API request: {e}") raise SafetyAlertDataError(f"Unexpected error: {e}")
def parse_alert_data(self, alerts: List[Dict[str, Any]]) -> Dict[str, Any]: """Parse and organize alert data.""" if not alerts: return { "total_alerts": 0, "latest_alert": None, "alert_types": {}, "alerts_by_type": {} }
# Count alerts by type alert_types: Dict[str, int] = {} alerts_by_type: Dict[str, List[Dict[str, Any]]] = {}
for alert in alerts: alert_type = alert.get("DSSTR_SE_NM", "기타") if alert_type not in alert_types: alert_types[alert_type] = 0 alerts_by_type[alert_type] = []
alert_types[alert_type] += 1 alerts_by_type[alert_type].append({ "message": alert.get("MSG_CN", ""), "created_date": alert.get("CREAT_DT", ""), "area": alert.get("RCV_AREA_NM", ""), "emergency_level": alert.get("EMRGNCY_STEP_NM", "") })
# Get latest alert latest_alert: Optional[Dict[str, Any]] = None if alerts: latest_alert = { "type": alerts[0].get("DSSTR_SE_NM", ""), "message": alerts[0].get("MSG_CN", ""), "created_date": alerts[0].get("CREAT_DT", ""), "area": alerts[0].get("RCV_AREA_NM", ""), "emergency_level": alerts[0].get("EMRGNCY_STEP_NM", "") }
return { "total_alerts": len(alerts), "latest_alert": latest_alert, "alert_types": alert_types, "alerts_by_type": alerts_by_type }

"""Safety Alert device for Home Assistant integration."""
from datetime import datetime
from typing import Dict, Any, Optional
import aiohttp
from homeassistant.helpers.device_registry import DeviceInfo
from homeassistant.helpers.update_coordinator import UpdateFailed

from .api import SafetyAlertApiClient
from .exceptions import SafetyAlertConnectionError, SafetyAlertDataError
from ..const import DOMAIN, LOGGER


class SafetyAlertDevice:
    """Safety Alert device representation."""

    def __init__(self, hass, entry_id: str, area_code: str, area_name: str, session: aiohttp.ClientSession):
        self.hass = hass
        self.entry_id = entry_id
        self.area_code = area_code
        self.area_name = area_name
        self.session = session
        self.api_client = SafetyAlertApiClient(self.session)

        self._name = f"안전알림 ({area_name})"
        self._unique_id = f"safety_alert_{area_code}"
        self._available = True
        self.data = {}
        self._last_update_success = None

    @property
    def unique_id(self) -> str:
        return self._unique_id

    @property
    def device_info(self) -> DeviceInfo:
        return DeviceInfo(
            identifiers={(DOMAIN, self._unique_id)},
            name=self._name,
            manufacturer="행정안전부",
            model="안전알림서비스",
            configuration_url="https://www.safekorea.go.kr",
        )

    @property
    def available(self) -> bool:
        return self._available

    async def async_update(self):
        """Fetch data from Safety Alert API."""
        try:
            # Get safety alerts
            alerts = await self.api_client.async_get_safety_alerts(self.area_code)

            # Parse alert data
            parsed_data = self.api_client.parse_alert_data(alerts)

            self.data = {
                "raw_alerts": alerts,
                "parsed_data": parsed_data,
                "last_updated": datetime.now().isoformat(),
            }

            self._available = True
            self._last_update_success = datetime.now()
            LOGGER.debug(f"Safety Alert data updated successfully for {self.area_name}")

        except (SafetyAlertConnectionError, SafetyAlertDataError) as err:
            self._available = False
            LOGGER.error(f"Error updating Safety Alert data for {self.area_name}: {err}")
            raise UpdateFailed(f"Error communicating with Safety Alert API: {err}")

        except Exception as err:
            self._available = False
            LOGGER.error(f"Unexpected error updating Safety Alert data for {self.area_name}: {err}")
            raise UpdateFailed(f"Unexpected error: {err}")

    def get_total_alerts(self) -> int:
        """Get total number of alerts."""
        if not self.data.get("parsed_data"):
            return 0
        return self.data["parsed_data"].get("total_alerts", 0)

    def get_latest_alert_message(self) -> Optional[str]:
        """Get latest alert message."""
        if not self.data.get("parsed_data"):
            return None
        latest = self.data["parsed_data"].get("latest_alert")
        return latest.get("message") if latest else None

    def get_latest_alert_type(self) -> Optional[str]:
        """Get latest alert type."""
        if not self.data.get("parsed_data"):
            return None
        latest = self.data["parsed_data"].get("latest_alert")
        return latest.get("type") if latest else None

    def get_alert_types_summary(self) -> str:
        """Get summary of alert types."""
        if not self.data.get("parsed_data"):
            return ""
        alert_types = self.data["parsed_data"].get("alert_types", {})
        if not alert_types:
            return "알림 없음"
        return ", ".join([f"{k}({v})" for k, v in alert_types.items()])

    async def async_close_session(self):
        """Close the aiohttp session."""
        if self.session:
            await self.session.close()
            self.session = None

